static inline float _relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static inline float _norm3(float a, float b, float c) {
  return sqrtf(a * a + b * b + c * c);
}

static void _normalize_frame(const float x_raw[SCALE_MODEL_CHANNELS], float x_norm[SCALE_MODEL_CHANNELS]) {
  for (int i = 0; i < SCALE_MODEL_CHANNELS; ++i) {
    x_norm[i] = (x_raw[i] - g_mean[i]) * g_inv_std[i];
  }
}

static float _baseline_update(scale_stream_t* st, float pressure_raw) {
  const int L = SCALE_BASELINE_WINDOW_SIZE;
  if (st->p_filled < (uint16_t)L) {
    st->p_buf[st->p_pos] = pressure_raw;
    st->p_sum += pressure_raw;
    st->p_pos = (uint16_t)((st->p_pos + 1) % L);
    st->p_filled += 1;
  } else {
    // overwrite oldest
    float old = st->p_buf[st->p_pos];
    st->p_sum -= old;
    st->p_buf[st->p_pos] = pressure_raw;
    st->p_sum += pressure_raw;
    st->p_pos = (uint16_t)((st->p_pos + 1) % L);
  }
  const float mean_p = (st->p_filled > 0) ? (st->p_sum / (float)st->p_filled) : 0.0f;
  return g_baseline_a * mean_p + g_baseline_b;
}

static void _xwin_update(scale_stream_t* st, const float x_norm[SCALE_MODEL_CHANNELS]) {
  const int L = SCALE_MODEL_WINDOW_SIZE;
  memcpy(st->x_norm[st->x_pos], x_norm, sizeof(float) * SCALE_MODEL_CHANNELS);
  st->x_pos = (uint16_t)((st->x_pos + 1) % L);
  if (st->x_filled < (uint16_t)L) {
    st->x_filled += 1;
  }
}

static inline int _xwin_ready(const scale_stream_t* st) {
  return (st->x_filled >= (uint16_t)SCALE_MODEL_WINDOW_SIZE);
}

static inline int _xwin_oldest(const scale_stream_t* st) {
  // when full, x_pos points to the next write position => oldest
  return _xwin_ready(st) ? (int)st->x_pos : 0;
}

// ---- MLP forward (reads from ring buffer directly; no extra big buffers) ----

static float _mlp_forward(const scale_stream_t* st, int oldest_idx) {
  // layer0: input -> h0
  // 注意：STM32上默认栈空间可能较小（Keil常见默认1KB），
  // 本模型在窗口满后会进入MLP推理，局部大数组可能造成栈溢出，进而表现为ready一直为0/数值异常。
  // 因此将中间缓冲改为静态区，降低栈占用（代价：函数非可重入，但本工程单线程调用可接受）。
  static float h0[184];
  const int L = SCALE_MODEL_WINDOW_SIZE;
#if (SCALE_MODEL_TYPE == 1)
  // baseline_factor: input uses IMU channels only (skip pressure at col 0)
  const int in_ch = SCALE_MODEL_CHANNELS - 1;
  const int x_off = 1;
#else
  // direct/residual: use all channels
  const int in_ch = SCALE_MODEL_CHANNELS;
  const int x_off = 0;
#endif
  const int in_dim = SCALE_MODEL_WINDOW_SIZE * in_ch;

  // compute hidden sizes from compiled weights
  const int h0_dim = 184;
  for (int o = 0; o < h0_dim; ++o) {
    float acc = g_b0[o];
    const float* w = &g_w0[o * in_dim];

    // 性能关键：避免在每个MAC里做除法/取模。
    // 这里按 (t,c) 双层循环线性读权重，ring buffer 用单次 wrap。
    int bi = oldest_idx;
    for (int t = 0; t < L; ++t) {
      const float* xrow = st->x_norm[bi];
      for (int c = 0; c < in_ch; ++c) {
        acc += (*w++) * xrow[c + x_off];
      }
      bi += 1;
      if (bi >= L) bi = 0;
    }
    h0[o] = _relu(acc);
  }

  static float h1[92];
  for (int o = 0; o < 92; ++o) {
    float acc = g_b1[o];
    const float* wrow = &g_w1[o * 184];
    for (int i = 0; i < 184; ++i) {
      acc += wrow[i] * h0[i];
    }
    h1[o] = _relu(acc);
  }

  // output layer
  float out = g_b2[0];
  const float* wrow = &g_w2[0];
  for (int i = 0; i < 92; ++i) {
    out += wrow[i] * h1[i];
  }
  return out;
}


static float _model_forward(const scale_stream_t* st, int oldest_idx) {
#if (SCALE_MODEL_TYPE == 0)
    // direct_mlp: y = mlp(x_norm_flat)
    return _mlp_forward(st, oldest_idx);

#elif (SCALE_MODEL_TYPE == 1) || (SCALE_MODEL_TYPE == 2)
  // mean standardized pressure over window
  float pz_sum = 0.0f;
  for (int t = 0; t < SCALE_MODEL_WINDOW_SIZE; ++t) {
    int bi = (oldest_idx + t) % SCALE_MODEL_WINDOW_SIZE;
    pz_sum += st->x_norm[bi][0];
  }
  float pz_mean = pz_sum / (float)SCALE_MODEL_WINDOW_SIZE;
  float p_raw_mean = pz_mean * g_pressure_std + g_pressure_mean;
  float y0 = g_model_baseline_a * p_raw_mean + g_model_baseline_b;

  #if (SCALE_MODEL_TYPE == 1)
    // baseline_factor: y = y0 * (1 + r_scale * tanh(mlp(imu)))
    float s = _mlp_forward(st, oldest_idx);
    float r = 1.0f + g_r_scale * tanhf(s);
    return y0 * r;
  #else
  // baseline_residual: y = y0 + d_scale * tanh(mlp(x))
  float d = _mlp_forward(st, oldest_idx);
  d = g_d_scale * tanhf(d);
  return y0 + d;
  #endif

#else
  #error "Unsupported SCALE_MODEL_TYPE"
#endif
}

void scale_stream_init(scale_stream_t* st) {
  if (st == NULL) return;
  memset(st, 0, sizeof(*st));
  st->use_model_gate = 0;
  st->use_tilt_comp = 0;
  st->fuse.gyro_on = 8.0f;
  st->fuse.gyro_off = 6.0f;
  st->fuse.acc_dev_on = 0.6f;
  st->fuse.acc_dev_off = 0.4f;
  st->fuse.g = 9.80665f;
  // tilt compensation defaults
  st->fuse.tilt_cos_on = 0.990f;
  st->fuse.tilt_cos_off = 0.995f;
  st->fuse.tilt_cos_min = 0.700f;
}

void scale_stream_step(scale_stream_t* st, const float x_raw[SCALE_MODEL_CHANNELS], scale_step_out_t* out) {
  if (st == NULL || x_raw == NULL || out == NULL) return;

  // baseline update uses raw pressure only
  float yb = _baseline_update(st, x_raw[0]);

  // motion metrics on raw units (match eval_stream.py)
  float ax = x_raw[1];
  float ay = x_raw[2];
  float az = x_raw[3];
  float gx = x_raw[4];
  float gy = x_raw[5];
  float gz = x_raw[6];
  float acc_norm = _norm3(ax, ay, az);
  float gyro_norm = _norm3(gx, gy, gz);
  float acc_dev = fabsf(acc_norm - st->fuse.g);

  // tilt metric (cos theta vs sensor Z axis)
  // Only meaningful when acc is close to gravity (i.e., calm conditions).
  float tilt_cos = 1.0f;
  if (acc_norm > 1e-6f) {
    tilt_cos = fabsf(az) / acc_norm;
    if (tilt_cos > 1.0f) tilt_cos = 1.0f;
  }
  // tilt hysteresis (track "long & large tilt" even if gyro is small)
  if (!st->use_tilt_comp) {
    if (tilt_cos < st->fuse.tilt_cos_on) st->use_tilt_comp = 1;
  } else {
    if (tilt_cos > st->fuse.tilt_cos_off) st->use_tilt_comp = 0;
  }

  // normalize + update feature window
  float xn[SCALE_MODEL_CHANNELS];
  _normalize_frame(x_raw, xn);
  _xwin_update(st, xn);

  // model output (only when window ready)
  float ym = NAN;
  int ready = _xwin_ready(st);
  // fused gating with hysteresis (match eval_stream.py)
  float yf = yb;
  if (ready) {
    int dyn_on = (gyro_norm > st->fuse.gyro_on) || (acc_dev > st->fuse.acc_dev_on);
    int calm_off = (gyro_norm < st->fuse.gyro_off) && (acc_dev < st->fuse.acc_dev_off);
    if (!st->use_model_gate && dyn_on) {
      st->use_model_gate = 1;
    } else if (st->use_model_gate && calm_off) {
      st->use_model_gate = 0;
    }

    // 性能优化：只有在 gate=ON 时才计算模型前向（MLP非常耗时）
    if (st->use_model_gate) {
      int oldest = _xwin_oldest(st);
      ym = _model_forward(st, oldest);
      if (isfinite(ym)) {
        yf = ym;
      }
    }
  }

  // ---- long-tilt compensation (calm + tilted) ----
  // Rationale: load cell measures normal force ~ mg*cos(theta) when the whole scale is tilted.
  // In long, low-dynamics tilt, gyro_norm is small and acc_norm ~ g, so baseline would under/over estimate.
  // We compensate using 1/cos(theta) only in calm conditions to avoid corrupting dynamics (linear accel makes tilt unreliable).
  if (!st->use_model_gate && st->use_tilt_comp) {
    // reuse "calm" thresholds
    int calm = (gyro_norm < st->fuse.gyro_off) && (acc_dev < st->fuse.acc_dev_off);
    if (calm) {
      float c = tilt_cos;
      if (c < st->fuse.tilt_cos_min) c = st->fuse.tilt_cos_min;
      if (c > 1e-6f) {
        yf = yf / c;
      }
    }
  }

  out->y_baseline = yb;
  out->y_model = ym;
  out->y_fused = yf;
  out->model_ready = (uint8_t)(ready ? 1 : 0);
  out->use_model_gate = (uint8_t)(st->use_model_gate ? 1 : 0);
}
